<?php if(empty($activeCategory)): ?><section class="empty-state"><h1>Topic not found</h1><p>That topic may have moved.</p><a class="button button-primary" href="<?= e(url('categories')) ?>">Browse all topics</a></section><?php else: ?><section class="page-intro category-intro"><a class="back-link" href="<?= e(url('categories')) ?>">← All topics</a><p class="eyebrow">TOPIC</p><h1><?= e($activeCategory['name']) ?></h1><p><?= e($activeCategory['description']) ?></p></section><div class="feed-column category-feed"><div class="section-heading"><h2>Questions in this topic</h2><a class="button button-outline" href="<?= e(url('ask')) ?>">＋ Ask a question</a></div><?php if($questions): foreach($questions as $q) include __DIR__.'/../includes/question_card.php';else: ?><div class="empty-state"><h3>No questions here yet</h3><p>Be the first to start a conversation in <?= e($activeCategory['name']) ?>.</p><a class="button button-primary" href="<?= e(url('ask')) ?>">Ask the first question</a></div><?php endif; ?></div><?php endif; ?>
